from typing import Optional, Union, Generic, TypeVar

T = TypeVar('T')

class Option(Generic[T]):
    def __init__(self, value: Optional[T] = None):
        self._value = value

    def is_some(self) -> bool:
        return self._value is not None

    def is_none(self) -> bool:
        return self._value is None

    def unwrap(self) -> T:
        if self._value is None:
            raise ValueError("Called unwrap on None")
        return self._value

class Some(Option[T]):
    def __init__(self, value: T):
        super().__init__(value)

class Nothing(Option[T]):
    def __init__(self):
        super().__init__(None)

def divide(a: float, b: float) -> Option[float]:
    if b == 0:
        return Nothing()
    return Some(a / b)

def main():
    # Test with divide(10, 2)
    result1 = divide(10, 2)
    if result1.is_some():
        print(f"Result: {result1.unwrap()}")
    else:
        print("Error: Division by zero")

    # Test with divide(10, 0)
    result2 = divide(10, 0)
    if result2.is_some():
        print(f"Result: {result2.unwrap()}")
    else:
        print("Error: Division by zero")

if __name__ == "__main__":
    main()

