def isBalanced(s):
    counter = 0
    for char in s:
        if char == '(':
            counter += 1
        elif char == ')':
            counter -= 1
        if counter < 0:
            return False
    return counter == 0


test_strings = ["(())", "(()", "())()", "()(())"]

for test in test_strings:
    result = isBalanced(test)
    print("true" if result else "false")

