class Leaf:
    def __init__(self, value):
        self.value = value

class Branch:
    def __init__(self, left, value, right):
        self.left = left
        self.value = value
        self.right = right

def treeSum(tree):
    if tree is None:
        return 0
    elif isinstance(tree, Leaf):
        return tree.value
    elif isinstance(tree, Branch):
        return treeSum(tree.left) + tree.value + treeSum(tree.right)
    else:
        return 0

# Create the tree
#         5
#        / \
#       3   8
#      / \   \
#     1   4   10
tree = Branch(
    Branch(
        Leaf(1),
        3,
        Leaf(4)
    ),
    5,
    Branch(
        None,
        8,
        Leaf(10)
    )
)

# Calculate and print the sum
result = treeSum(tree)
print(result)

