  let args = getArgs();

  match args {
    [] => print("No arguments provided"),
    ::(filename, _) => {
      let content = readFile(filename);
      let lines = split(content, "\n");
      let numbers = map(parseNumber, lines);
      let result = sum(numbers);
      print(show(result))
    }
  }
}

