import std/fs (readFile, writeFile)
import std/string (split, trim, find, stringToInt)
import std/json (encode, jo, ja, kv, js, jnum)

func createCsvContent() -> string =
  "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com"

func isValidEmail(email: string) -> bool =
  find(email, "@") >= 0

func isValidAge(ageStr: string) -> bool =
  match stringToInt(trim(ageStr)) {
    Some(n) => n > 0,
    None => false
  }

func parseAge(ageStr: string) -> int =
  match stringToInt(trim(ageStr)) {
    Some(n) => n,
    None => 0
  }

func processRowHelper(name: string, ageStr: string, email: string) -> (bool, string, int, string) =
  let trimmedName = trim(name) in
  let trimmedAge = trim(ageStr) in
  let trimmedEmail = trim(email) in
  if isValidAge(trimmedAge) && isValidEmail(trimmedEmail)
  then (true, trimmedName, parseAge(trimmedAge), trimmedEmail)
  else (false, "", 0, "")

func processRow(fields: [string]) -> (bool, string, int, string) =
  match fields {
    f1 :: f2 :: f3 :: _ => processRowHelper(f1, f2, f3),
    _ => (false, "", 0, "")
  }

func filterValidRows(rows: [(bool, string, int, string)]) -> [(bool, string, int, string)] =
  match rows {
    [] => [],
    r :: rest => match r {
      (valid, _, _, _) => if valid
                          then r :: filterValidRows(rest)
                          else filterValidRows(rest)
    }
  }

func parseDataRows(lines: [string]) -> [(bool, string, int, string)] =
  match lines {
    [] => [],
    line :: rest => 
      let fields = split(line, ",") in
      let row = processRow(fields) in
      row :: parseDataRows(rest)
  }

func skipHeader(lines: [string]) -> [string] =
  match lines {
    [] => [],
    _ :: rest => rest
  }

func countRows(rows: [(bool, string, int, string)]) -> int =
  match rows {
    [] => 0,
    _ :: rest => 1 + countRows(rest)
  }

func rowToJson(row: (bool, string, int, string)) -> string =
  match row {
    (_, name, age, email) => encode(jo([
      kv("name", js(name)),
      kv("age", jnum(intToFloat(age))),
      kv("email", js(email))
    ]))
  }

func rowsToJsonList(rows: [(bool, string, int, string)]) -> [string] =
  match rows {
    [] => [],
    r :: rest => rowToJson(r) :: rowsToJsonList(rest)
  }

func joinWithComma(parts: [string]) -> string =
  match parts {
    [] => "",
    x :: [] => x,
    x :: rest => x ++ "," ++ joinWithComma(rest)
  }

func buildJsonArray(rows: [(bool, string, int, string)]) -> string =
  "[" ++ joinWithComma(rowsToJsonList(rows)) ++ "]"

export func main() -> () ! {IO, FS} {
  let csvContent = createCsvContent();
  writeFile("users.csv", csvContent);
  let content = readFile("users.csv");
  let lines = split(content, "\n");
  let dataLines = skipHeader(lines);
  let allRows = parseDataRows(dataLines);
  let validRows = filterValidRows(allRows);
  let jsonOutput = buildJsonArray(validRows);
  writeFile("users.json", jsonOutput);
  let count = countRows(validRows);
  print("Converted " ++ show(count) ++ " valid rows to users.json")
}

