from typing import TypeVar, Generic, Callable

# Type-level markers for pure and effectful computations
T = TypeVar('T')

class Pure(Generic[T]):
    """Wrapper for pure values - cannot contain IO effects"""
    def __init__(self, value: T):
        self._value = value

    def run(self) -> T:
        return self._value

class IO(Generic[T]):
    """Wrapper for effectful computations"""
    def __init__(self, effect: Callable[[], T]):
        self._effect = effect

    def run(self) -> T:
        return self._effect()

# PURE FUNCTIONS - return Pure[T], cannot call IO
def double(x: int) -> Pure[int]:
    """Pure function: returns x * 2 with no side effects"""
    return Pure(x * 2)

def add(a: int, b: int) -> Pure[int]:
    """Pure function: returns a + b with no side effects"""
    return Pure(a + b)

# EFFECTFUL FUNCTIONS - return IO[T], can call pure functions
def printResult(label: str, value: int) -> IO[None]:
    """Effectful function: prints label and value (has IO)"""
    def effect():
        print(f"{label}: {value}")
    return IO(effect)

def compute_and_print() -> IO[None]:
    """Effectful function: calls pure functions and prints result"""
    def effect():
        # Call pure functions and extract their values
        result1 = double(5).run()
        result2 = add(result1, 3).run()
        # Call effectful function
        printResult("Result", result2).run()
    return IO(effect)

if __name__ == "__main__":
    # Run the effectful computation
    compute_and_print().run()

