from typing import TypeVar, Callable
from functools import wraps

# Effect marker types
class IO:
    """Marker for IO effects"""
    pass

class FS:
    """Marker for filesystem effects"""
    pass

# Decorator to mark functions with effects
def has_effects(*effects):
    """Decorator to explicitly mark function effects"""
    def decorator(func):
        func.__effects__ = effects
        @wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapper
    return decorator

# PURE function - no effect annotations
def computeSum(a: int, b: int) -> int:
    return a + b

# IO function - marked with IO effect
@has_effects(IO)
def printSum(a: int, b: int) -> None:
    result = computeSum(a, b)
    print(f"Sum: {result}")

# IO+FS function - marked with both effects
@has_effects(IO, FS)
def logToFile(filename: str, message: str) -> None:
    with open(filename, 'w') as f:
        f.write(message)

def main():
    # Call computeSum and store result
    result = computeSum(10, 20)

    # Call printSum to print "Sum: 30"
    printSum(10, 20)

    # Call logToFile to write to file
    logToFile("output.txt", "Sum was 30")

    # Print "Done"
    print("Done")

if __name__ == "__main__":
    main()

