from typing import Generic, TypeVar, Union

T = TypeVar('T')


class Ok(Generic[T]):
    def __init__(self, value: T):
        self.value = value

    def __repr__(self):
        return f"Ok({self.value})"


class Err:
    def __init__(self, message: str):
        self.message = message

    def __repr__(self):
        return f"Err({self.message})"


Result = Union[Ok[T], Err]


def parse_int(s: str) -> Result[int]:
    try:
        return Ok(int(s))
    except ValueError:
        return Err("Invalid integer")


def divide_safe(a: int, b: int) -> Result[int]:
    if b == 0:
        return Err("Division by zero")
    return Ok(a // b)


def print_result(result: Result) -> None:
    if isinstance(result, Ok):
        print(f"Result: {result.value}")
    elif isinstance(result, Err):
        print(f"Error: {result.message}")


# Test case 1: parse_int("10") then divide by 2
result1 = parse_int("10")
if isinstance(result1, Ok):
    result1 = divide_safe(result1.value, 2)
print_result(result1)

# Test case 2: parse_int("10") then divide by 0
result2 = parse_int("10")
if isinstance(result2, Ok):
    result2 = divide_safe(result2.value, 0)
print_result(result2)

