    for item in lst:
        if item == x:
            return True
    return False

def enqueue(x, queue):
    queue.append(x)

def bfs(graph, start):
    visited = []
    queue = []

    enqueue(start, queue)

    while queue:
        node = queue.pop(0)

        if not contains(node, visited):
            visited.append(node)

            for graph_node, neighbors in graph:
                if graph_node == node:
                    for neighbor in neighbors:
                        if not contains(neighbor, visited):
                            enqueue(neighbor, queue)
                    break

    return visited

