  | TApp(Term, Term)

export func subst(term: Term, v: string, repl: Term) -> Term {
  match term {
    TVar(name) =>
      if name == v
      then repl
      else TVar(name),
    TLam(param, body) =>
      if param == v
      then TLam(param, body)
      else TLam(param, subst(body, v, repl)),
    TApp(f, a) =>
      TApp(subst(f, v, repl), subst(a, v, repl))
