from dataclasses import dataclass

@dataclass
class TVar:
    name: str

    def __repr__(self):
        return self.name

@dataclass
class TLam:
    var: str
    body: 'Term'

@dataclass
class TApp:
    func: 'Term'
    arg: 'Term'

Term = TVar | TLam | TApp

def subst(term: Term, var: str, replacement: Term) -> Term:
    if isinstance(term, TVar):
        return replacement if term.name == var else term
    elif isinstance(term, TLam):
        if term.var == var:
            return term
        else:
            return TLam(term.var, subst(term.body, var, replacement))
    elif isinstance(term, TApp):
        return TApp(subst(term.func, var, replacement), subst(term.arg, var, replacement))
    return term

def eval(term: Term) -> Term:
    if isinstance(term, TVar):
        return term
    elif isinstance(term, TLam):
        return term
    elif isinstance(term, TApp):
        func = eval(term.func)
        arg = eval(term.arg)
        if isinstance(func, TLam):
            body = subst(func.body, func.var, arg)
            return eval(body)
        else:
            return TApp(func, arg)
    return term

if __name__ == "__main__":
    expr = TApp(TApp(TLam("x", TLam("y", TVar("x"))), TVar("1")), TVar("2"))
    result = eval(expr)
    print(result)

