// Count occurrences of a string in a list
export func countOccurrences(target: string, items: [string]) -> int {
  match items {
    [] => 0,
    x :: rest => {
      let count = countOccurrences(target, rest);
      if _str_eq(x, target) then count + 1 else count
    }
  }
}

// Extract log levels from lines
export func extractLevels(lines: [string]) -> [string] {
  match lines {
    [] => [],
    line :: rest => {
      let parts = split(line, " ");
      let level = getLevel(parts, 0);
      level :: extractLevels(rest)
    }
  }
}

// Get the level (3rd element after date and time)
export func getLevel(parts: [string], index: int) -> string {
  match parts {
    [] => "",
    p :: rest => if index == 2 then p else getLevel(rest, index + 1)
  }
}

// Extract unique usernames from log lines
export func extractUsers(lines: [string]) -> [string] {
  match lines {
    [] => [],
    line :: rest => {
      let users = extractUsers(rest);
      let user = extractUserFromLine(line);
      if _str_eq(user, "") then users else addUnique(user, users)
    }
  }
}

// Extract username from a line (only from "logged in:" or "logged out:" lines)
export func extractUserFromLine(line: string) -> string {
  let loggedInIdx = find(line, "logged in: ");
  let loggedOutIdx = find(line, "logged out: ");
  if loggedInIdx != -1
  then {
    let afterColon = substring(line, loggedInIdx + 11, _str_len(line));
    trim(afterColon)
  }
  else if loggedOutIdx != -1
  then {
    let afterColon = substring(line, loggedOutIdx + 12, _str_len(line));
    trim(afterColon)
  }
  else ""
}

// Add item to list if not already present
export func addUnique(item: string, items: [string]) -> [string] {
  if contains(item, items)
  then items
  else item :: items
}

// Check if list contains an item
export func contains(item: string, items: [string]) -> bool {
  match items {
    [] => false,
    x :: rest => if _str_eq(x, item) then true else contains(item, rest)
  }
}

// Sort strings alphabetically (bubble sort)
export func sortStrings(items: [string]) -> [string] {
  bubbleSort(items, length(items))
}

// Bubble sort helper
export func bubbleSort(items: [string], passes: int) -> [string] {
  if passes <= 0
  then items
  else bubbleSort(bubblePass(items), passes - 1)
}

// Single pass of bubble sort
export func bubblePass(items: [string]) -> [string] {
  match items {
    [] => [],
    [x] => [x],
    x :: y :: rest => {
      if _str_compare(x, y) > 0
      then y :: bubblePass(x :: rest)
      else x :: bubblePass(y :: rest)
    }
  }
}

// Join strings with separator
export func joinStrings(items: [string], sep: string) -> string {
  match items {
    [] => "",
    [x] => x,
    x :: rest => x ++ sep ++ joinStrings(rest, sep)
  }
}

