  print("INFO: " ++ show(infoCount) ++ " (" ++ show(infoPercent) ++ "%)");
  print("ERROR: " ++ show(errorCount) ++ " (" ++ show(errorPercent) ++ "%)");
  print("WARNING: " ++ show(warningCount) ++ " (" ++ show(warningPercent) ++ "%)");
