def merge(xs, ys):
    result = []
    i = j = 0

    while i < len(xs) and j < len(ys):
        if xs[i] <= ys[j]:
            result.append(xs[i])
            i += 1
        else:
            result.append(ys[j])
            j += 1

    while i < len(xs):
        result.append(xs[i])
        i += 1

    while j < len(ys):
        result.append(ys[j])
        j += 1

    return result


def split(xs):
    mid = len(xs) // 2
    return xs[:mid], xs[mid:]


