class Num:
    def __init__(self, value):
        self.value = value

class Var:
    def __init__(self, name):
        self.name = name

class Add:
    def __init__(self, left, right):
        self.left = left
        self.right = right

class Mul:
    def __init__(self, left, right):
        self.left = left
        self.right = right

class Let:
    def __init__(self, name, expr, body):
        self.name = name
        self.expr = expr
        self.body = body

# Lookup function
def lookup(name, env):
    for var_name, var_value in env:
        if var_name == name:
            return var_value
    raise KeyError(f"Variable {name} not found")

# Eval function
def eval(expr, env):
    if isinstance(expr, Num):
        return expr.value
    elif isinstance(expr, Var):
        return lookup(expr.name, env)
    elif isinstance(expr, Add):
        left_val = eval(expr.left, env)
        right_val = eval(expr.right, env)
        return left_val + right_val
    elif isinstance(expr, Mul):
        left_val = eval(expr.left, env)
        right_val = eval(expr.right, env)
        return left_val * right_val
    elif isinstance(expr, Let):
        value = eval(expr.expr, env)
        new_env = [(expr.name, value)] + env
        return eval(expr.body, new_env)
    else:
        raise ValueError(f"Unknown expression type: {type(expr)}")

