def transition(state: State, event: Event) -> State:
    """State transition function with exhaustive pattern matching"""

    # Handle Reset event for all states
    if isinstance(event, Reset):
        return Green(20)

    # Handle Tick event for each state
    if isinstance(event, Tick):
        if isinstance(state, Green):
            if state.timer > 1:
                return Green(state.timer - 1)
            else:
                return Yellow(3)

        elif isinstance(state, Yellow):
            if state.timer > 1:
                return Yellow(state.timer - 1)
            else:
                return Red(10)

        elif isinstance(state, Red):
            if state.timer > 1:
                return Red(state.timer - 1)
            else:
                return Green(20)

    # This should never be reached due to type constraints
    raise ValueError(f"Unhandled combination: {state}, {event}")

