      let r = simplify(right);
      match l {
        Const(0) => r,
        _ => match r {
          Const(0) => l,
          _ => Add(l, r)
        }
      }
    },
    Mul(left, right) => {
      let l = simplify(left);
      let r = simplify(right);
      match l {
        Const(0) => Const(0),
        Const(1) => r,
        _ => match r {
          Const(0) => Const(0),
          Const(1) => l,
          _ => Mul(l, r)
