class Const:
    def __init__(self, value):
        self.value = value

    def __str__(self):
        return str(self.value)

class Var:
    def __init__(self, name):
        self.name = name

    def __str__(self):
        return self.name

class Add:
    def __init__(self, left, right):
        self.left = left
        self.right = right

    def __str__(self):
        return f"{self.left} + {self.right}"

class Mul:
    def __init__(self, left, right):
        self.left = left
        self.right = right

    def __str__(self):
        if isinstance(self.left, Const):
            return f"{self.left}{self.right}"
        return f"{self.left} * {self.right}"

def diff(expr, var):
    if isinstance(expr, Const):
        return Const(0)
    elif isinstance(expr, Var):
        return Const(1) if expr.name == var else Const(0)
    elif isinstance(expr, Add):
        return Add(diff(expr.left, var), diff(expr.right, var))
    elif isinstance(expr, Mul):
        return Add(
            Mul(expr.left, diff(expr.right, var)),
            Mul(expr.right, diff(expr.left, var))
        )

def simplify(expr):
    if isinstance(expr, Const) or isinstance(expr, Var):
        return expr
    elif isinstance(expr, Add):
        left = simplify(expr.left)
        right = simplify(expr.right)

        if isinstance(left, Const) and left.value == 0:
            return right
        if isinstance(right, Const) and right.value == 0:
            return left

        # Combine x + x = 2x
        if isinstance(left, Var) and isinstance(right, Var) and left.name == right.name:
            return Mul(Const(2), left)

        # Combine (a + x) + x = a + 2x
        if isinstance(left, Add) and isinstance(right, Var):
            if isinstance(left.right, Var) and left.right.name == right.name:
                return Add(left.left, Mul(Const(2), right))

        return Add(left, right)
    elif isinstance(expr, Mul):
        left = simplify(expr.left)
        right = simplify(expr.right)

        if isinstance(left, Const) and left.value == 0:
            return Const(0)
        if isinstance(right, Const) and right.value == 0:
            return Const(0)
        if isinstance(left, Const) and left.value == 1:
            return right
        if isinstance(right, Const) and right.value == 1:
            return left

        return Mul(left, right)

def main():
    expr = Add(Add(Mul(Var("x"), Var("x")), Mul(Const(3), Var("x"))), Const(5))
    derivative = diff(expr, "x")
    simplified = simplify(derivative)
    print(simplified)

