      Node(mapTree(fn, left), fn(v), mapTree(fn, right))
  }

export func foldTree(fn: int -> int -> int, acc: int, tree: Tree) -> int =
  match tree {
    Leaf(v) => fn(acc)(v),
    Node(left, v, right) => {
      let accLeft = foldTree(fn, acc, left);
      let accV = fn(accLeft)(v);
      foldTree(fn, accV, right)
    }
  }

export func concat(xs: [int], ys: [int]) -> [int] =
  match xs {
    [] => ys,
    x :: rest => x :: concat(rest, ys)
  }

export func treeToList(tree: Tree) -> [int] =
  match tree {
    Leaf(v) => [v],
    Node(left, v, right) => {
      let leftList = treeToList(left);
      let rightList = treeToList(right);
      concat(leftList, v :: rightList)
    }
  }

export func filterNonZero(xs: [int]) -> [int] =
  match xs {
    [] => [],
    x :: rest =>
      if x == 0
      then filterNonZero(rest)
      else x :: filterNonZero(rest)
  }

export func treeDepth(tree: Tree) -> int =
  match tree {
    Leaf(_) => 1,
    Node(left, _, right) => {
      let leftDepth = treeDepth(left);
      let rightDepth = treeDepth(right);
      if leftDepth > rightDepth
      then 1 + leftDepth
      else 1 + rightDepth
    }
  }

export func showList(xs: [int]) -> string =
  "[" ++ showListInner(xs) ++ "]"

export func showListInner(xs: [int]) -> string =
  match xs {
    [] => "",
    [x] => show(x),
    x :: rest => show(x) ++ ", " ++ showListInner(rest)
  }

export func main() -> () ! {IO} {
  let tree =
    Node(
      Node(Leaf(1), 3, Leaf(0)),
      5,
      Node(Leaf(7), 8, Leaf(9))
    );

  let originalList = filterNonZero(treeToList(tree));
  println("Original: " ++ showList(originalList));

  let doubledTree = mapTree(\x. x * 2, tree);
  let doubledList = filterNonZero(treeToList(doubledTree));
  println("Doubled: " ++ showList(doubledList));

  let sum = foldTree(\a. \b. a + b, 0, tree);
  println("Sum: " ++ show(sum));

  let depth = treeDepth(tree);
  println("Depth: " ++ show(depth))
}

