module benchmark/solution

type Type = TVar(string) | TInt | TBool | TFunc(Type, Type)

type UnifyResult = Success([(string, Type)]) | Failure

func strEq(a: string, b: string) -> bool = _str_eq(a, b)

func lookupVar(name: string, subst: [(string, Type)]) -> Type {
  match subst {
    [] => TVar(name),
    pair :: rest => match pair {
      (n, t) => if strEq(n, name) then t else lookupVar(name, rest)
    }
  }
}

func apply(subst: [(string, Type)], ty: Type) -> Type {
  match ty {
    TVar(name) => lookupVar(name, subst),
    TInt => TInt,
    TBool => TBool,
    TFunc(arg, res) => TFunc(apply(subst, arg), apply(subst, res))
  }
}

func concatSubst(s1: [(string, Type)], s2: [(string, Type)]) -> [(string, Type)] {
  match s1 {
    [] => s2,
    pair :: rest => pair :: concatSubst(rest, s2)
  }
}

func unify(t1: Type, t2: Type) -> UnifyResult {
  match t1 {
    TInt => match t2 {
      TInt => Success([]),
      TVar(b) => Success([(b, TInt)]),
      _ => Failure
    },
    TBool => match t2 {
      TBool => Success([]),
      TVar(b) => Success([(b, TBool)]),
      _ => Failure
    },
    TVar(a) => Success([(a, t2)]),
    TFunc(arg1, res1) => match t2 {
      TFunc(arg2, res2) => {
        match unify(arg1, arg2) {
          Failure => Failure,
          Success(s1) => {
            let newRes1 = apply(s1, res1);
            let newRes2 = apply(s1, res2);
            match unify(newRes1, newRes2) {
              Failure => Failure,
              Success(s2) => Success(concatSubst(s1, s2))
            }
          }
        }
      },
      TVar(b) => Success([(b, t1)]),
      _ => Failure
    }
  }
}

func typeToString(ty: Type) -> string {
  match ty {
    TVar(name) => name,
    TInt => "TInt",
    TBool => "TBool",
    TFunc(arg, res) => "TFunc(" ++ typeToString(arg) ++ ", " ++ typeToString(res) ++ ")"
  }
}

func printSubst(subst: [(string, Type)]) -> () ! {IO} {
  match subst {
    [] => (),
    pair :: rest => match pair {
      (name, ty) => {
        print(name ++ " = " ++ typeToString(ty));
        printSubst(rest)
      }
    }
  }
}

export func main() -> () ! {IO} {
  let t1 = TFunc(TVar("a"), TInt);
  let t2 = TFunc(TBool, TVar("b"));
  match unify(t1, t2) {
    Success(subst) => printSubst(subst),
    Failure => print("Unification failed")
  }
}

