from dataclasses import dataclass
from typing import List, Tuple, Union

@dataclass
class TVar:
    name: str

@dataclass
class TInt:
    pass

@dataclass
class TBool:
    pass

@dataclass
class TFunc:
    arg: 'Type'
    result: 'Type'

Type = Union[TVar, TInt, TBool, TFunc]
Substitution = List[Tuple[str, Type]]

def apply(subst: Substitution, t: Type) -> Type:
    if isinstance(t, TVar):
        for var_name, var_type in subst:
            if var_name == t.name:
                return apply(subst, var_type)
        return t
    elif isinstance(t, TInt):
        return t
    elif isinstance(t, TBool):
        return t
    elif isinstance(t, TFunc):
        return TFunc(apply(subst, t.arg), apply(subst, t.result))
    return t

def unify(t1: Type, t2: Type) -> Substitution:
    t1 = t1 if not isinstance(t1, type) else t1()
    t2 = t2 if not isinstance(t2, type) else t2()

    if isinstance(t1, TInt) and isinstance(t2, TInt):
        return []
    elif isinstance(t1, TBool) and isinstance(t2, TBool):
        return []
    elif isinstance(t1, TVar):
        return [(t1.name, t2)]
    elif isinstance(t2, TVar):
        return [(t2.name, t1)]
    elif isinstance(t1, TFunc) and isinstance(t2, TFunc):
        s1 = unify(t1.arg, t2.arg)
        t1_result_applied = apply(s1, t1.result)
        t2_result_applied = apply(s1, t2.result)
        s2 = unify(t1_result_applied, t2_result_applied)
        return s1 + s2
    else:
        raise ValueError("Cannot unify types")

def type_to_string(t: Type) -> str:
    if isinstance(t, TVar):
        return f"TVar({t.name})"
    elif isinstance(t, TInt):
        return "TInt"
    elif isinstance(t, TBool):
        return "TBool"
    elif isinstance(t, TFunc):
        return f"TFunc({type_to_string(t.arg)}, {type_to_string(t.result)})"
    return str(t)

def main():
    t1 = TFunc(TVar("a"), TInt())
    t2 = TFunc(TBool(), TVar("b"))

    subst = unify(t1, t2)

    for var_name, var_type in subst:
        if isinstance(var_type, TBool):
            print(f"{var_name} = TBool")
        elif isinstance(var_type, TInt):
            print(f"{var_name} = TInt")

if __name__ == "__main__":
    main()
